    probe: { anlegen: 'Einen Vertrag „Test" mit 0 €/Monat über „＋ Vertrag" anlegen.', loeschen: 'Löschen gibt es auf dieser Seite nicht — ein Probe-Vertrag bleibt stehen und zählt, solange er aktiv ist, im MRR mit. Darum lieber die Übungswelt nutzen.' },
    landetIn: [{ text: 'Heute (fällige Wartungen)', href: '/dashboard/heute' }, { text: 'SLA-Bericht', href: '/dashboard/itassets/sla' }],
