    landetIn: [{ text: 'CMR-Frachtbrief (Tour zur Auswahl)', href: '/dashboard/logistik/cmr' }, { text: 'Tankkarte & Maut (Abgleich Tag mit Tour)', href: '/dashboard/logistik/tankkarten' }],
