    probe: { anlegen: '„＋ Neuer Frachtbrief“ und nur „💾 Entwurf speichern“.', loeschen: 'Löschen gibt es nicht. Der Chef kann den Entwurf mit „stornieren“ (mit Rückfrage) aus dem Verkehr ziehen — die Nummer bleibt belegt.' },
    vorher: [{ text: 'Firmenname im Betriebsprofil (Absender/Frachtführer)', href: '/dashboard/einstellungen' }, { text: 'Tour in der Logistik, wenn der Brief zu einer Tour gehört', href: '/dashboard/logistik' }],
